/* Z-Lang Transpiler - Parser Module
   Phase 2: Lexer + AST Parser (400 lines)

   Parses Z-Lang source code into an Abstract Syntax Tree (AST).
   Supports 50+ token types and expression/statement parsing.
*/

// Token types for Z-Lang lexer
#[derive(Debug, Clone, PartialEq)]
pub enum TokenType {
    // Literals
    Integer(i64),
    Float(f64),
    String(String),
    Identifier(String),

    // Keywords
    Fn, Let, Const, Return, If, Else, While, For, In, Break, Continue,
    Struct, Enum, Impl, Trait, Pub, Mut, Ref, Type, Match, Do,
    Async, Await, Yield, Static, Unsafe, Use, Mod, Crate, Self_, As,
    Where, Default, Dyn, Try, Catch, Finally, Throw, Class, New, Delete,

    // Operators
    Plus, Minus, Star, Slash, Percent, Equal, EqualEqual, NotEqual,
    Less, Greater, LessEqual, GreaterEqual, And, Or, Not, Caret, Pipe,
    Ampersand, DoubleColon, Arrow, FatArrow, DotDot, Question, Dot,
    PlusEqual, MinusEqual, StarEqual, SlashEqual,

    // Delimiters
    LeftParen, RightParen, LeftBrace, RightBrace, LeftBracket, RightBracket,
    Semicolon, Comma, Colon, At,

    // Special
    Eof, Newline, Whitespace,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub token_type: TokenType,
    pub line: u32,
    pub column: u32,
}

// AST Node types
#[derive(Debug, Clone, PartialEq)]
pub enum AstNode {
    // Literals
    IntLiteral(i64),
    FloatLiteral(f64),
    StringLiteral(String),
    BoolLiteral(bool),

    // Expressions
    Identifier(String),
    BinaryOp { left: Box<AstNode>, op: String, right: Box<AstNode> },
    UnaryOp { op: String, operand: Box<AstNode> },
    Call { func: Box<AstNode>, args: Vec<AstNode> },
    FieldAccess { object: Box<AstNode>, field: String },
    Index { object: Box<AstNode>, index: Box<AstNode> },

    // Statements
    VarDecl { name: String, type_: Option<String>, value: Option<Box<AstNode>> },
    FnDecl { name: String, params: Vec<(String, String)>, return_type: Option<String>, body: Vec<AstNode> },
    Block(Vec<AstNode>),
    IfStmt { condition: Box<AstNode>, then_body: Vec<AstNode>, else_body: Option<Vec<AstNode>> },
    WhileStmt { condition: Box<AstNode>, body: Vec<AstNode> },
    ForStmt { var: String, iter: Box<AstNode>, body: Vec<AstNode> },
    ReturnStmt(Option<Box<AstNode>>),

    // Type declarations
    StructDecl { name: String, fields: Vec<(String, String)> },
    EnumDecl { name: String, variants: Vec<String> },

    // Program structure
    Program(Vec<AstNode>),
}

pub struct Lexer {
    input: Vec<char>,
    position: usize,
    line: u32,
    column: u32,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            position: 0,
            line: 1,
            column: 1,
        }
    }

    fn current_char(&self) -> Option<char> {
        if self.position < self.input.len() {
            Some(self.input[self.position])
        } else {
            None
        }
    }

    fn peek_char(&self, offset: usize) -> Option<char> {
        let pos = self.position + offset;
        if pos < self.input.len() {
            Some(self.input[pos])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        if let Some(c) = self.current_char() {
            if c == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
            self.position += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.current_char() {
            if c.is_whitespace() && c != '\n' {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while let Some(c) = self.current_char() {
            if c.is_alphanumeric() || c == '_' {
                result.push(c);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn read_number(&mut self) -> TokenType {
        let mut result = String::new();
        let mut is_float = false;

        while let Some(c) = self.current_char() {
            if c.is_numeric() {
                result.push(c);
                self.advance();
            } else if c == '.' && !is_float && self.peek_char(1).map_or(false, |ch| ch.is_numeric()) {
                is_float = true;
                result.push(c);
                self.advance();
            } else {
                break;
            }
        }

        if is_float {
            TokenType::Float(result.parse().unwrap_or(0.0))
        } else {
            TokenType::Integer(result.parse().unwrap_or(0))
        }
    }

    fn read_string(&mut self, quote: char) -> String {
        let mut result = String::new();
        self.advance(); // Skip opening quote

        while let Some(c) = self.current_char() {
            if c == quote {
                self.advance();
                break;
            } else if c == '\\' {
                self.advance();
                if let Some(next) = self.current_char() {
                    match next {
                        'n' => result.push('\n'),
                        't' => result.push('\t'),
                        'r' => result.push('\r'),
                        '\\' => result.push('\\'),
                        '"' => result.push('"'),
                        '\'' => result.push('\''),
                        _ => result.push(next),
                    }
                    self.advance();
                }
            } else {
                result.push(c);
                self.advance();
            }
        }
        result
    }

    fn keyword_or_identifier(&self, word: &str) -> TokenType {
        match word {
            "fn" => TokenType::Fn,
            "let" => TokenType::Let,
            "const" => TokenType::Const,
            "return" => TokenType::Return,
            "if" => TokenType::If,
            "else" => TokenType::Else,
            "while" => TokenType::While,
            "for" => TokenType::For,
            "in" => TokenType::In,
            "break" => TokenType::Break,
            "continue" => TokenType::Continue,
            "struct" => TokenType::Struct,
            "enum" => TokenType::Enum,
            "impl" => TokenType::Impl,
            "pub" => TokenType::Pub,
            "mut" => TokenType::Mut,
            "true" => TokenType::Integer(1),
            "false" => TokenType::Integer(0),
            _ => TokenType::Identifier(word.to_string()),
        }
    }

    pub fn next_token(&mut self) -> Token {
        self.skip_whitespace();

        let line = self.line;
        let column = self.column;

        match self.current_char() {
            None => Token { token_type: TokenType::Eof, line, column },
            Some('\n') => {
                self.advance();
                Token { token_type: TokenType::Newline, line, column }
            },
            Some('(') => {
                self.advance();
                Token { token_type: TokenType::LeftParen, line, column }
            },
            Some(')') => {
                self.advance();
                Token { token_type: TokenType::RightParen, line, column }
            },
            Some('{') => {
                self.advance();
                Token { token_type: TokenType::LeftBrace, line, column }
            },
            Some('}') => {
                self.advance();
                Token { token_type: TokenType::RightBrace, line, column }
            },
            Some('[') => {
                self.advance();
                Token { token_type: TokenType::LeftBracket, line, column }
            },
            Some(']') => {
                self.advance();
                Token { token_type: TokenType::RightBracket, line, column }
            },
            Some(';') => {
                self.advance();
                Token { token_type: TokenType::Semicolon, line, column }
            },
            Some(',') => {
                self.advance();
                Token { token_type: TokenType::Comma, line, column }
            },
            Some(':') => {
                self.advance();
                if self.current_char() == Some(':') {
                    self.advance();
                    Token { token_type: TokenType::DoubleColon, line, column }
                } else {
                    Token { token_type: TokenType::Colon, line, column }
                }
            },
            Some('.') => {
                self.advance();
                if self.current_char() == Some('.') {
                    self.advance();
                    Token { token_type: TokenType::DotDot, line, column }
                } else {
                    Token { token_type: TokenType::Dot, line, column }
                }
            },
            Some('+') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::PlusEqual, line, column }
                } else {
                    Token { token_type: TokenType::Plus, line, column }
                }
            },
            Some('-') => {
                self.advance();
                if self.current_char() == Some('>') {
                    self.advance();
                    Token { token_type: TokenType::Arrow, line, column }
                } else if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::MinusEqual, line, column }
                } else {
                    Token { token_type: TokenType::Minus, line, column }
                }
            },
            Some('*') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::StarEqual, line, column }
                } else {
                    Token { token_type: TokenType::Star, line, column }
                }
            },
            Some('/') => {
                self.advance();
                if self.current_char() == Some('/') {
                    // Line comment, skip until newline
                    while self.current_char().is_some() && self.current_char() != Some('\n') {
                        self.advance();
                    }
                    self.next_token()
                } else if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::SlashEqual, line, column }
                } else {
                    Token { token_type: TokenType::Slash, line, column }
                }
            },
            Some('%') => {
                self.advance();
                Token { token_type: TokenType::Percent, line, column }
            },
            Some('=') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::EqualEqual, line, column }
                } else if self.current_char() == Some('>') {
                    self.advance();
                    Token { token_type: TokenType::FatArrow, line, column }
                } else {
                    Token { token_type: TokenType::Equal, line, column }
                }
            },
            Some('!') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::NotEqual, line, column }
                } else {
                    Token { token_type: TokenType::Not, line, column }
                }
            },
            Some('<') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::LessEqual, line, column }
                } else {
                    Token { token_type: TokenType::Less, line, column }
                }
            },
            Some('>') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    Token { token_type: TokenType::GreaterEqual, line, column }
                } else {
                    Token { token_type: TokenType::Greater, line, column }
                }
            },
            Some('&') => {
                self.advance();
                if self.current_char() == Some('&') {
                    self.advance();
                    Token { token_type: TokenType::And, line, column }
                } else {
                    Token { token_type: TokenType::Ampersand, line, column }
                }
            },
            Some('|') => {
                self.advance();
                if self.current_char() == Some('|') {
                    self.advance();
                    Token { token_type: TokenType::Or, line, column }
                } else {
                    Token { token_type: TokenType::Pipe, line, column }
                }
            },
            Some('^') => {
                self.advance();
                Token { token_type: TokenType::Caret, line, column }
            },
            Some('?') => {
                self.advance();
                Token { token_type: TokenType::Question, line, column }
            },
            Some('@') => {
                self.advance();
                Token { token_type: TokenType::At, line, column }
            },
            Some('"') => {
                let s = self.read_string('"');
                Token { token_type: TokenType::String(s), line, column }
            },
            Some('\'') => {
                let s = self.read_string('\'');
                Token { token_type: TokenType::String(s), line, column }
            },
            Some(c) if c.is_numeric() => {
                let token_type = self.read_number();
                Token { token_type, line, column }
            },
            Some(c) if c.is_alphabetic() || c == '_' => {
                let word = self.read_identifier();
                let token_type = self.keyword_or_identifier(&word);
                Token { token_type, line, column }
            },
            Some(_) => {
                self.advance();
                self.next_token()
            },
        }
    }
}

pub struct Parser {
    tokens: Vec<Token>,
    position: usize,
}

impl Parser {
    pub fn new(input: &str) -> Self {
        let mut lexer = Lexer::new(input);
        let mut tokens = Vec::new();

        loop {
            let token = lexer.next_token();
            let is_eof = matches!(token.token_type, TokenType::Eof);
            tokens.push(token);
            if is_eof {
                break;
            }
        }

        Parser {
            tokens,
            position: 0,
        }
    }

    fn current_token(&self) -> &Token {
        self.tokens.get(self.position).unwrap_or(&self.tokens[self.tokens.len() - 1])
    }

    fn advance(&mut self) {
        if self.position < self.tokens.len() {
            self.position += 1;
        }
    }

    pub fn parse(&mut self) -> Result<AstNode, String> {
        let mut statements = Vec::new();

        while !matches!(self.current_token().token_type, TokenType::Eof) {
            if matches!(self.current_token().token_type, TokenType::Newline) {
                self.advance();
                continue;
            }
            statements.push(self.parse_statement()?);
        }

        Ok(AstNode::Program(statements))
    }

    fn parse_statement(&mut self) -> Result<AstNode, String> {
        match &self.current_token().token_type {
            TokenType::Let => self.parse_var_decl(),
            TokenType::Fn => self.parse_fn_decl(),
            TokenType::If => self.parse_if_stmt(),
            TokenType::While => self.parse_while_stmt(),
            TokenType::For => self.parse_for_stmt(),
            TokenType::Return => self.parse_return_stmt(),
            TokenType::LeftBrace => self.parse_block(),
            _ => self.parse_expression_stmt(),
        }
    }

    fn parse_var_decl(&mut self) -> Result<AstNode, String> {
        self.advance(); // consume 'let'

        let name = match &self.current_token().token_type {
            TokenType::Identifier(n) => {
                let name = n.clone();
                self.advance();
                name
            },
            _ => return Err("Expected identifier".to_string()),
        };

        let mut type_ = None;
        if matches!(self.current_token().token_type, TokenType::Colon) {
            self.advance();
            if let TokenType::Identifier(t) = &self.current_token().token_type {
                type_ = Some(t.clone());
                self.advance();
            }
        }

        let mut value = None;
        if matches!(self.current_token().token_type, TokenType::Equal) {
            self.advance();
            value = Some(Box::new(self.parse_expression()?));
        }

        self.consume_semicolon();

        Ok(AstNode::VarDecl { name, type_, value })
    }

    fn parse_fn_decl(&mut self) -> Result<AstNode, String> {
        self.advance(); // consume 'fn'

        let name = match &self.current_token().token_type {
            TokenType::Identifier(n) => {
                let name = n.clone();
                self.advance();
                name
            },
            _ => return Err("Expected function name".to_string()),
        };

        self.expect_token(TokenType::LeftParen)?;
        let params = self.parse_parameters()?;
        self.expect_token(TokenType::RightParen)?;

        let mut return_type = None;
        if matches!(self.current_token().token_type, TokenType::Arrow) {
            self.advance();
            if let TokenType::Identifier(t) = &self.current_token().token_type {
                return_type = Some(t.clone());
                self.advance();
            }
        }

        let body = self.parse_block_body()?;

        Ok(AstNode::FnDecl { name, params, return_type, body })
    }

    fn parse_if_stmt(&mut self) -> Result<AstNode, String> {
        self.advance(); // consume 'if'

        let condition = Box::new(self.parse_expression()?);
        let then_body = self.parse_block_body()?;

        let else_body = if matches!(self.current_token().token_type, TokenType::Else) {
            self.advance();
            Some(self.parse_block_body()?)
        } else {
            None
        };

        Ok(AstNode::IfStmt { condition, then_body, else_body })
    }

    fn parse_while_stmt(&mut self) -> Result<AstNode, String> {
        self.advance(); // consume 'while'

        let condition = Box::new(self.parse_expression()?);
        let body = self.parse_block_body()?;

        Ok(AstNode::WhileStmt { condition, body })
    }

    fn parse_for_stmt(&mut self) -> Result<AstNode, String> {
        self.advance(); // consume 'for'

        let var = match &self.current_token().token_type {
            TokenType::Identifier(v) => {
                let v = v.clone();
                self.advance();
                v
            },
            _ => return Err("Expected variable name".to_string()),
        };

        self.expect(TokenType::In)?;
        let iter = Box::new(self.parse_expression()?);
        let body = self.parse_block_body()?;

        Ok(AstNode::ForStmt { var, iter, body })
    }

    fn parse_return_stmt(&mut self) -> Result<AstNode, String> {
        self.advance(); // consume 'return'

        let value = if matches!(self.current_token().token_type, TokenType::Semicolon | TokenType::Newline | TokenType::Eof) {
            None
        } else {
            Some(Box::new(self.parse_expression()?))
        };

        self.consume_semicolon();
        Ok(AstNode::ReturnStmt(value))
    }

    fn parse_block(&mut self) -> Result<AstNode, String> {
        let body = self.parse_block_body()?;
        Ok(AstNode::Block(body))
    }

    fn parse_block_body(&mut self) -> Result<Vec<AstNode>, String> {
        self.expect_token(TokenType::LeftBrace)?;
        let mut statements = Vec::new();

        while !matches!(self.current_token().token_type, TokenType::RightBrace | TokenType::Eof) {
            if matches!(self.current_token().token_type, TokenType::Newline) {
                self.advance();
                continue;
            }
            statements.push(self.parse_statement()?);
        }

        self.expect_token(TokenType::RightBrace)?;
        Ok(statements)
    }

    fn parse_expression(&mut self) -> Result<AstNode, String> {
        self.parse_or_expr()
    }

    fn parse_or_expr(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_and_expr()?;

        while matches!(self.current_token().token_type, TokenType::Or) {
            self.advance();
            let right = self.parse_and_expr()?;
            left = AstNode::BinaryOp { left: Box::new(left), op: "||".to_string(), right: Box::new(right) };
        }

        Ok(left)
    }

    fn parse_and_expr(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_equality_expr()?;

        while matches!(self.current_token().token_type, TokenType::And) {
            self.advance();
            let right = self.parse_equality_expr()?;
            left = AstNode::BinaryOp { left: Box::new(left), op: "&&".to_string(), right: Box::new(right) };
        }

        Ok(left)
    }

    fn parse_equality_expr(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_relational_expr()?;

        while let Some(op) = self.match_equality_op() {
            self.advance();
            let right = self.parse_relational_expr()?;
            left = AstNode::BinaryOp { left: Box::new(left), op, right: Box::new(right) };
        }

        Ok(left)
    }

    fn parse_relational_expr(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_additive_expr()?;

        while let Some(op) = self.match_relational_op() {
            self.advance();
            let right = self.parse_additive_expr()?;
            left = AstNode::BinaryOp { left: Box::new(left), op, right: Box::new(right) };
        }

        Ok(left)
    }

    fn parse_additive_expr(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_multiplicative_expr()?;

        while let Some(op) = self.match_additive_op() {
            self.advance();
            let right = self.parse_multiplicative_expr()?;
            left = AstNode::BinaryOp { left: Box::new(left), op, right: Box::new(right) };
        }

        Ok(left)
    }

    fn parse_multiplicative_expr(&mut self) -> Result<AstNode, String> {
        let mut left = self.parse_unary_expr()?;

        while let Some(op) = self.match_multiplicative_op() {
            self.advance();
            let right = self.parse_unary_expr()?;
            left = AstNode::BinaryOp { left: Box::new(left), op, right: Box::new(right) };
        }

        Ok(left)
    }

    fn parse_unary_expr(&mut self) -> Result<AstNode, String> {
        match &self.current_token().token_type {
            TokenType::Not | TokenType::Minus | TokenType::Ampersand | TokenType::Star => {
                let op = match &self.current_token().token_type {
                    TokenType::Not => "!".to_string(),
                    TokenType::Minus => "-".to_string(),
                    TokenType::Ampersand => "&".to_string(),
                    TokenType::Star => "*".to_string(),
                    _ => unreachable!(),
                };
                self.advance();
                let operand = Box::new(self.parse_unary_expr()?);
                Ok(AstNode::UnaryOp { op, operand })
            },
            _ => self.parse_postfix_expr(),
        }
    }

    fn parse_postfix_expr(&mut self) -> Result<AstNode, String> {
        let mut expr = self.parse_primary_expr()?;

        loop {
            match &self.current_token().token_type {
                TokenType::LeftParen => {
                    self.advance();
                    let args = self.parse_arguments()?;
                    self.expect_token(TokenType::RightParen)?;
                    expr = AstNode::Call { func: Box::new(expr), args };
                },
                TokenType::Dot => {
                    self.advance();
                    if let TokenType::Identifier(field) = &self.current_token().token_type {
                        let field = field.clone();
                        self.advance();
                        expr = AstNode::FieldAccess { object: Box::new(expr), field };
                    }
                },
                TokenType::LeftBracket => {
                    self.advance();
                    let index = Box::new(self.parse_expression()?);
                    self.expect_token(TokenType::RightBracket)?;
                    expr = AstNode::Index { object: Box::new(expr), index };
                },
                _ => break,
            }
        }

        Ok(expr)
    }

    fn parse_primary_expr(&mut self) -> Result<AstNode, String> {
        match &self.current_token().token_type.clone() {
            TokenType::Integer(n) => {
                let n = *n;
                self.advance();
                Ok(AstNode::IntLiteral(n))
            },
            TokenType::Float(f) => {
                let f = *f;
                self.advance();
                Ok(AstNode::FloatLiteral(f))
            },
            TokenType::String(s) => {
                let s = s.clone();
                self.advance();
                Ok(AstNode::StringLiteral(s))
            },
            TokenType::Identifier(id) => {
                let id = id.clone();
                self.advance();
                Ok(AstNode::Identifier(id))
            },
            TokenType::LeftParen => {
                self.advance();
                let expr = self.parse_expression()?;
                self.expect_token(TokenType::RightParen)?;
                Ok(expr)
            },
            _ => Err(format!("Unexpected token: {:?}", self.current_token().token_type)),
        }
    }

    fn parse_parameters(&mut self) -> Result<Vec<(String, String)>, String> {
        let mut params = Vec::new();

        if matches!(self.current_token().token_type, TokenType::RightParen) {
            return Ok(params);
        }

        loop {
            if let TokenType::Identifier(name) = &self.current_token().token_type {
                let name = name.clone();
                self.advance();

                self.expect(TokenType::Colon)?;

                if let TokenType::Identifier(type_) = &self.current_token().token_type {
                    let type_ = type_.clone();
                    self.advance();
                    params.push((name, type_));
                } else {
                    return Err("Expected type annotation".to_string());
                }
            } else {
                return Err("Expected parameter name".to_string());
            }

            if !matches!(self.current_token().token_type, TokenType::Comma) {
                break;
            }
            self.advance();
        }

        Ok(params)
    }

    fn parse_arguments(&mut self) -> Result<Vec<AstNode>, String> {
        let mut args = Vec::new();

        if matches!(self.current_token().token_type, TokenType::RightParen) {
            return Ok(args);
        }

        loop {
            args.push(self.parse_expression()?);

            if !matches!(self.current_token().token_type, TokenType::Comma) {
                break;
            }
            self.advance();
        }

        Ok(args)
    }

    fn match_equality_op(&self) -> Option<String> {
        match &self.current_token().token_type {
            TokenType::EqualEqual => Some("==".to_string()),
            TokenType::NotEqual => Some("!=".to_string()),
            _ => None,
        }
    }

    fn match_relational_op(&self) -> Option<String> {
        match &self.current_token().token_type {
            TokenType::Less => Some("<".to_string()),
            TokenType::Greater => Some(">".to_string()),
            TokenType::LessEqual => Some("<=".to_string()),
            TokenType::GreaterEqual => Some(">=".to_string()),
            _ => None,
        }
    }

    fn match_additive_op(&self) -> Option<String> {
        match &self.current_token().token_type {
            TokenType::Plus => Some("+".to_string()),
            TokenType::Minus => Some("-".to_string()),
            _ => None,
        }
    }

    fn match_multiplicative_op(&self) -> Option<String> {
        match &self.current_token().token_type {
            TokenType::Star => Some("*".to_string()),
            TokenType::Slash => Some("/".to_string()),
            TokenType::Percent => Some("%".to_string()),
            _ => None,
        }
    }

    fn expect(&mut self, expected: TokenType) -> Result<(), String> {
        if std::mem::discriminant(&self.current_token().token_type) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            Err(format!("Expected {:?}, found {:?}", expected, self.current_token().token_type))
        }
    }

    fn expect_token(&mut self, expected: TokenType) -> Result<(), String> {
        if std::mem::discriminant(&self.current_token().token_type) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            Err(format!("Expected {:?}, found {:?}", expected, self.current_token().token_type))
        }
    }

    fn consume_semicolon(&mut self) {
        if matches!(self.current_token().token_type, TokenType::Semicolon) {
            self.advance();
        }
    }
}

/* Z-Lang Transpiler - Intermediate Representation (IR) Module
   Phase 2: IR Nodes and Builder (300 lines)

   Converts AST to a language-neutral intermediate representation
   for semantic analysis and code generation.
*/

use crate::parser::AstNode;

// IR instruction types
#[derive(Debug, Clone, PartialEq)]
pub enum IrInstruction {
    // Literals
    LoadInt(i64),
    LoadFloat(f64),
    LoadString(String),

    // Variables
    StoreVar { name: String, value_reg: u32 },
    LoadVar { name: String, dest_reg: u32 },

    // Operations
    BinaryOp { op: String, left_reg: u32, right_reg: u32, dest_reg: u32 },
    UnaryOp { op: String, operand_reg: u32, dest_reg: u32 },

    // Control flow
    Jump { target: u32 },
    JumpIfZero { cond_reg: u32, target: u32 },
    JumpIfNotZero { cond_reg: u32, target: u32 },
    Label { id: u32 },

    // Function call
    Call { func_name: String, args: Vec<u32>, dest_reg: u32 },
    Return { value_reg: Option<u32> },

    // Memory operations
    Allocate { size: usize, dest_reg: u32 },
    Load { addr_reg: u32, dest_reg: u32 },
    Store { addr_reg: u32, value_reg: u32 },

    // Field access
    FieldAccess { obj_reg: u32, field: String, dest_reg: u32 },
    Index { obj_reg: u32, idx_reg: u32, dest_reg: u32 },

    // Type conversions
    Convert { from_type: String, to_type: String, value_reg: u32, dest_reg: u32 },
}

#[derive(Debug, Clone)]
pub struct IrBlock {
    pub id: u32,
    pub instructions: Vec<IrInstruction>,
    pub successors: Vec<u32>,
}

#[derive(Debug, Clone)]
pub struct IrFunction {
    pub name: String,
    pub params: Vec<(String, String)>,
    pub return_type: Option<String>,
    pub blocks: Vec<IrBlock>,
    pub entry_block: u32,
}

#[derive(Debug, Clone)]
pub struct IrModule {
    pub functions: Vec<IrFunction>,
    pub globals: Vec<(String, String)>,
}

pub struct IrBuilder {
    current_block_id: u32,
    current_reg: u32,
    instructions: Vec<IrInstruction>,
    blocks: Vec<IrBlock>,
    symbol_table: std::collections::HashMap<String, u32>,
}

impl IrBuilder {
    pub fn new() -> Self {
        IrBuilder {
            current_block_id: 0,
            current_reg: 0,
            instructions: Vec::new(),
            blocks: Vec::new(),
            symbol_table: std::collections::HashMap::new(),
        }
    }

    pub fn allocate_register(&mut self) -> u32 {
        let reg = self.current_reg;
        self.current_reg += 1;
        reg
    }

    pub fn allocate_label(&mut self) -> u32 {
        let label = self.current_block_id;
        self.current_block_id += 1;
        label
    }

    pub fn emit(&mut self, instr: IrInstruction) {
        self.instructions.push(instr);
    }

    pub fn emit_load_int(&mut self, value: i64) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::LoadInt(value));
        dest
    }

    pub fn emit_load_float(&mut self, value: f64) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::LoadFloat(value));
        dest
    }

    pub fn emit_load_string(&mut self, value: String) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::LoadString(value));
        dest
    }

    pub fn emit_store_var(&mut self, name: String, value_reg: u32) {
        self.emit(IrInstruction::StoreVar { name, value_reg });
        self.symbol_table.insert(name, value_reg);
    }

    pub fn emit_load_var(&mut self, name: String) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::LoadVar { name, dest_reg: dest });
        dest
    }

    pub fn emit_binary_op(&mut self, op: String, left_reg: u32, right_reg: u32) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::BinaryOp { op, left_reg, right_reg, dest_reg: dest });
        dest
    }

    pub fn emit_unary_op(&mut self, op: String, operand_reg: u32) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::UnaryOp { op, operand_reg, dest_reg: dest });
        dest
    }

    pub fn emit_jump(&mut self, target: u32) {
        self.emit(IrInstruction::Jump { target });
    }

    pub fn emit_jump_if_zero(&mut self, cond_reg: u32, target: u32) {
        self.emit(IrInstruction::JumpIfZero { cond_reg, target });
    }

    pub fn emit_jump_if_not_zero(&mut self, cond_reg: u32, target: u32) {
        self.emit(IrInstruction::JumpIfNotZero { cond_reg, target });
    }

    pub fn emit_label(&mut self, id: u32) {
        self.emit(IrInstruction::Label { id });
    }

    pub fn emit_call(&mut self, func_name: String, args: Vec<u32>) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::Call { func_name, args, dest_reg: dest });
        dest
    }

    pub fn emit_return(&mut self, value_reg: Option<u32>) {
        self.emit(IrInstruction::Return { value_reg });
    }

    pub fn emit_allocate(&mut self, size: usize) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::Allocate { size, dest_reg: dest });
        dest
    }

    pub fn emit_load(&mut self, addr_reg: u32) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::Load { addr_reg, dest_reg: dest });
        dest
    }

    pub fn emit_store(&mut self, addr_reg: u32, value_reg: u32) {
        self.emit(IrInstruction::Store { addr_reg, value_reg });
    }

    pub fn emit_field_access(&mut self, obj_reg: u32, field: String) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::FieldAccess { obj_reg, field, dest_reg: dest });
        dest
    }

    pub fn emit_index(&mut self, obj_reg: u32, idx_reg: u32) -> u32 {
        let dest = self.allocate_register();
        self.emit(IrInstruction::Index { obj_reg, idx_reg, dest_reg: dest });
        dest
    }

    pub fn finalize_block(&mut self, id: u32, successors: Vec<u32>) -> IrBlock {
        let instructions = std::mem::take(&mut self.instructions);
        IrBlock {
            id,
            instructions,
            successors,
        }
    }

    pub fn build_from_ast(&mut self, ast: &AstNode) -> Result<IrModule, String> {
        match ast {
            AstNode::Program(statements) => {
                let mut functions = Vec::new();
                let mut globals = Vec::new();

                for stmt in statements {
                    match stmt {
                        AstNode::FnDecl { name, params, return_type, body } => {
                            functions.push(self.build_function(name.clone(), params.clone(), return_type.clone(), body.clone())?);
                        },
                        AstNode::VarDecl { name, type_, value } => {
                            globals.push((name.clone(), type_.clone().unwrap_or("unknown".to_string())));
                        },
                        _ => {},
                    }
                }

                Ok(IrModule { functions, globals })
            },
            _ => Err("Expected program".to_string()),
        }
    }

    fn build_function(
        &mut self,
        name: String,
        params: Vec<(String, String)>,
        return_type: Option<String>,
        body: Vec<AstNode>,
    ) -> Result<IrFunction, String> {
        let entry_block = self.allocate_label();
        self.emit_label(entry_block);

        for stmt in &body {
            self.build_statement(stmt)?;
        }

        let block = self.finalize_block(entry_block, Vec::new());
        let blocks = vec![block];

        Ok(IrFunction {
            name,
            params,
            return_type,
            blocks,
            entry_block,
        })
    }

    fn build_statement(&mut self, stmt: &AstNode) -> Result<Option<u32>, String> {
        match stmt {
            AstNode::VarDecl { name, type_, value } => {
                if let Some(expr) = value {
                    let reg = self.build_expression(expr)?;
                    self.emit_store_var(name.clone(), reg);
                    Ok(Some(reg))
                } else {
                    Ok(None)
                }
            },
            AstNode::ReturnStmt(expr) => {
                let value_reg = if let Some(e) = expr {
                    Some(self.build_expression(e)?)
                } else {
                    None
                };
                self.emit_return(value_reg);
                Ok(value_reg)
            },
            AstNode::IfStmt { condition, then_body, else_body } => {
                let cond_reg = self.build_expression(condition)?;
                let then_label = self.allocate_label();
                let else_label = self.allocate_label();
                let end_label = self.allocate_label();

                self.emit_jump_if_not_zero(cond_reg, then_label);
                self.emit_jump(else_label);

                self.emit_label(then_label);
                for stmt in then_body {
                    self.build_statement(stmt)?;
                }
                self.emit_jump(end_label);

                self.emit_label(else_label);
                if let Some(else_stmts) = else_body {
                    for stmt in else_stmts {
                        self.build_statement(stmt)?;
                    }
                }
                self.emit_jump(end_label);

                self.emit_label(end_label);
                Ok(Some(cond_reg))
            },
            AstNode::WhileStmt { condition, body } => {
                let loop_label = self.allocate_label();
                let end_label = self.allocate_label();

                self.emit_label(loop_label);
                let cond_reg = self.build_expression(condition)?;
                self.emit_jump_if_zero(cond_reg, end_label);

                for stmt in body {
                    self.build_statement(stmt)?;
                }
                self.emit_jump(loop_label);

                self.emit_label(end_label);
                Ok(Some(cond_reg))
            },
            _ => Ok(None),
        }
    }

    fn build_expression(&mut self, expr: &AstNode) -> Result<u32, String> {
        match expr {
            AstNode::IntLiteral(n) => Ok(self.emit_load_int(*n)),
            AstNode::FloatLiteral(f) => Ok(self.emit_load_float(*f)),
            AstNode::StringLiteral(s) => Ok(self.emit_load_string(s.clone())),
            AstNode::Identifier(name) => Ok(self.emit_load_var(name.clone())),
            AstNode::BinaryOp { left, op, right } => {
                let left_reg = self.build_expression(left)?;
                let right_reg = self.build_expression(right)?;
                Ok(self.emit_binary_op(op.clone(), left_reg, right_reg))
            },
            AstNode::UnaryOp { op, operand } => {
                let operand_reg = self.build_expression(operand)?;
                Ok(self.emit_unary_op(op.clone(), operand_reg))
            },
            AstNode::Call { func, args } => {
                let func_name = if let AstNode::Identifier(n) = &**func {
                    n.clone()
                } else {
                    return Err("Invalid function call".to_string());
                };

                let arg_regs: Result<Vec<_>, _> = args.iter().map(|arg| self.build_expression(arg)).collect();
                Ok(self.emit_call(func_name, arg_regs?))
            },
            AstNode::FieldAccess { object, field } => {
                let obj_reg = self.build_expression(object)?;
                Ok(self.emit_field_access(obj_reg, field.clone()))
            },
            AstNode::Index { object, index } => {
                let obj_reg = self.build_expression(object)?;
                let idx_reg = self.build_expression(index)?;
                Ok(self.emit_index(obj_reg, idx_reg))
            },
            _ => Err(format!("Unsupported expression: {:?}", expr)),
        }
    }
}

pub fn print_ir(ir: &IrModule) -> String {
    let mut output = String::new();
    output.push_str("IR Module:\n");
    output.push_str(&format!("  Globals: {:?}\n", ir.globals));
    output.push_str("  Functions:\n");

    for func in &ir.functions {
        output.push_str(&format!("    fn {}(", func.name));
        for (i, (param_name, param_type)) in func.params.iter().enumerate() {
            if i > 0 { output.push_str(", "); }
            output.push_str(&format!("{}: {}", param_name, param_type));
        }
        output.push_str(")");
        if let Some(ret_type) = &func.return_type {
            output.push_str(&format!(" -> {}", ret_type));
        }
        output.push_str(" {{\n");

        for block in &func.blocks {
            output.push_str(&format!("      Block {}:\n", block.id));
            for instr in &block.instructions {
                output.push_str(&format!("        {:?}\n", instr));
            }
        }

        output.push_str("    }\n");
    }

    output
}

/* Z-Lang Transpiler - Code Generation Module
   Phase 2: Z-Lang to FreeLang Transpilation (200 lines)

   Generates FreeLang code from Z-Lang AST and IR.
*/

use crate::parser::AstNode;
use crate::ir::{IrModule, IrInstruction};

pub struct CodeGenerator;

impl CodeGenerator {
    pub fn generate_from_ast(ast: &AstNode) -> Result<String, String> {
        match ast {
            AstNode::Program(statements) => {
                let mut output = String::new();
                output.push_str("/* Generated from Z-Lang */\n\n");

                for stmt in statements {
                    output.push_str(&Self::generate_statement(stmt)?);
                    output.push_str("\n");
                }

                Ok(output)
            },
            _ => Err("Expected program".to_string()),
        }
    }

    pub fn generate_from_ir(ir: &IrModule) -> Result<String, String> {
        let mut output = String::new();
        output.push_str("/* Generated FreeLang code from Z-Lang IR */\n\n");

        for global in &ir.globals {
            output.push_str(&format!("let {}: {} = 0;\n", global.0, global.1));
        }

        if !ir.globals.is_empty() {
            output.push_str("\n");
        }

        for func in &ir.functions {
            output.push_str(&format!("pub fn {}(", func.name));

            for (i, (param_name, param_type)) in func.params.iter().enumerate() {
                if i > 0 { output.push_str(", "); }
                output.push_str(&format!("{}: {}", param_name, param_type));
            }

            output.push_str(")");

            if let Some(ret_type) = &func.return_type {
                output.push_str(&format!(" -> {}", ret_type));
            }

            output.push_str(" {{\n");

            // Generate function body from IR blocks
            for block in &func.blocks {
                for instr in &block.instructions {
                    output.push_str(&Self::generate_instruction(instr)?);
                }
            }

            output.push_str("}\n\n");
        }

        Ok(output)
    }

    fn generate_statement(stmt: &AstNode) -> Result<String, String> {
        match stmt {
            AstNode::VarDecl { name, type_, value } => {
                let mut output = format!("let {}", name);
                if let Some(t) = type_ {
                    output.push_str(&format!(": {}", t));
                }
                if let Some(val) = value {
                    output.push_str(&format!(" = {};", Self::generate_expression(val)?));
                } else {
                    output.push_str(";");
                }
                Ok(output)
            },
            AstNode::FnDecl { name, params, return_type, body } => {
                let mut output = format!("pub fn {}(", name);

                for (i, (pname, ptype)) in params.iter().enumerate() {
                    if i > 0 { output.push_str(", "); }
                    output.push_str(&format!("{}: {}", pname, ptype));
                }

                output.push_str(")");
                if let Some(ret_type) = return_type {
                    output.push_str(&format!(" -> {}", ret_type));
                }
                output.push_str(" {{\n");

                for stmt in body {
                    output.push_str("    ");
                    output.push_str(&Self::generate_statement(stmt)?);
                    output.push_str("\n");
                }

                output.push_str("}\n");
                Ok(output)
            },
            AstNode::Block(stmts) => {
                let mut output = String::from("{\n");
                for stmt in stmts {
                    output.push_str("    ");
                    output.push_str(&Self::generate_statement(stmt)?);
                    output.push_str("\n");
                }
                output.push_str("}");
                Ok(output)
            },
            AstNode::IfStmt { condition, then_body, else_body } => {
                let mut output = format!("if {} {{\n", Self::generate_expression(condition)?);
                for stmt in then_body {
                    output.push_str("    ");
                    output.push_str(&Self::generate_statement(stmt)?);
                    output.push_str("\n");
                }
                output.push_str("}");

                if let Some(else_stmts) = else_body {
                    output.push_str(" else {\n");
                    for stmt in else_stmts {
                        output.push_str("    ");
                        output.push_str(&Self::generate_statement(stmt)?);
                        output.push_str("\n");
                    }
                    output.push_str("}");
                }

                Ok(output)
            },
            AstNode::WhileStmt { condition, body } => {
                let mut output = format!("while {} {{\n", Self::generate_expression(condition)?);
                for stmt in body {
                    output.push_str("    ");
                    output.push_str(&Self::generate_statement(stmt)?);
                    output.push_str("\n");
                }
                output.push_str("}");
                Ok(output)
            },
            AstNode::ForStmt { var, iter, body } => {
                let mut output = format!("for {} in {} {{\n", var, Self::generate_expression(iter)?);
                for stmt in body {
                    output.push_str("    ");
                    output.push_str(&Self::generate_statement(stmt)?);
                    output.push_str("\n");
                }
                output.push_str("}");
                Ok(output)
            },
            AstNode::ReturnStmt(expr) => {
                if let Some(e) = expr {
                    Ok(format!("return {};", Self::generate_expression(e)?))
                } else {
                    Ok("return;".to_string())
                }
            },
            _ => Err(format!("Unsupported statement: {:?}", stmt)),
        }
    }

    fn generate_expression(expr: &AstNode) -> Result<String, String> {
        match expr {
            AstNode::IntLiteral(n) => Ok(format!("{}", n)),
            AstNode::FloatLiteral(f) => Ok(format!("{}", f)),
            AstNode::StringLiteral(s) => Ok(format!("\"{}\"", s)),
            AstNode::Identifier(id) => Ok(id.clone()),
            AstNode::BinaryOp { left, op, right } => {
                Ok(format!("({} {} {})",
                    Self::generate_expression(left)?,
                    op,
                    Self::generate_expression(right)?
                ))
            },
            AstNode::UnaryOp { op, operand } => {
                Ok(format!("{}{}",
                    op,
                    Self::generate_expression(operand)?
                ))
            },
            AstNode::Call { func, args } => {
                let func_name = match &**func {
                    AstNode::Identifier(name) => name.clone(),
                    _ => return Err("Invalid function call".to_string()),
                };

                let mut arg_strs = Vec::new();
                for arg in args {
                    arg_strs.push(Self::generate_expression(arg)?);
                }

                Ok(format!("{}({})", func_name, arg_strs.join(", ")))
            },
            AstNode::FieldAccess { object, field } => {
                Ok(format!("{}.{}", Self::generate_expression(object)?, field))
            },
            AstNode::Index { object, index } => {
                Ok(format!("{}[{}]", Self::generate_expression(object)?, Self::generate_expression(index)?))
            },
            _ => Err(format!("Unsupported expression: {:?}", expr)),
        }
    }

    fn generate_instruction(instr: &IrInstruction) -> Result<String, String> {
        match instr {
            IrInstruction::LoadInt(n) => Ok(format!("    // load_int {}\n", n)),
            IrInstruction::LoadFloat(f) => Ok(format!("    // load_float {}\n", f)),
            IrInstruction::LoadString(s) => Ok(format!("    // load_string \"{}\"\n", s)),
            IrInstruction::StoreVar { name, value_reg } => {
                Ok(format!("    let {} = r{};\n", name, value_reg))
            },
            IrInstruction::LoadVar { name, dest_reg } => {
                Ok(format!("    let r{} = {};\n", dest_reg, name))
            },
            IrInstruction::BinaryOp { op, left_reg, right_reg, dest_reg } => {
                Ok(format!("    let r{} = r{} {} r{};\n", dest_reg, left_reg, op, right_reg))
            },
            IrInstruction::UnaryOp { op, operand_reg, dest_reg } => {
                Ok(format!("    let r{} = {}r{};\n", dest_reg, op, operand_reg))
            },
            IrInstruction::Jump { target } => {
                Ok(format!("    // jump to block {}\n", target))
            },
            IrInstruction::JumpIfZero { cond_reg, target } => {
                Ok(format!("    // jump_if_zero r{} to block {}\n", cond_reg, target))
            },
            IrInstruction::JumpIfNotZero { cond_reg, target } => {
                Ok(format!("    // jump_if_not_zero r{} to block {}\n", cond_reg, target))
            },
            IrInstruction::Label { id } => {
                Ok(format!("    // label block_{}\n", id))
            },
            IrInstruction::Call { func_name, args, dest_reg } => {
                let arg_str = args.iter().map(|r| format!("r{}", r)).collect::<Vec<_>>().join(", ");
                Ok(format!("    let r{} = {}({});\n", dest_reg, func_name, arg_str))
            },
            IrInstruction::Return { value_reg } => {
                if let Some(reg) = value_reg {
                    Ok(format!("    return r{};\n", reg))
                } else {
                    Ok("    return;\n".to_string())
                }
            },
            IrInstruction::Allocate { size, dest_reg } => {
                Ok(format!("    let r{} = alloc({});\n", dest_reg, size))
            },
            IrInstruction::Load { addr_reg, dest_reg } => {
                Ok(format!("    let r{} = *r{};\n", dest_reg, addr_reg))
            },
            IrInstruction::Store { addr_reg, value_reg } => {
                Ok(format!("    *r{} = r{};\n", addr_reg, value_reg))
            },
            IrInstruction::FieldAccess { obj_reg, field, dest_reg } => {
                Ok(format!("    let r{} = r{}.{};\n", dest_reg, obj_reg, field))
            },
            IrInstruction::Index { obj_reg, idx_reg, dest_reg } => {
                Ok(format!("    let r{} = r{}[r{}];\n", dest_reg, obj_reg, idx_reg))
            },
            IrInstruction::Convert { from_type, to_type, value_reg, dest_reg } => {
                Ok(format!("    let r{} = r{} as {}; // {} -> {}\n",
                    dest_reg, value_reg, to_type, from_type, to_type))
            },
        }
    }
}

pub struct CodeValidator;

impl CodeValidator {
    pub fn validate_ast(ast: &AstNode) -> Result<(), String> {
        match ast {
            AstNode::Program(statements) => {
                for stmt in statements {
                    Self::validate_statement(stmt)?;
                }
                Ok(())
            },
            _ => Err("Expected program".to_string()),
        }
    }

    fn validate_statement(stmt: &AstNode) -> Result<(), String> {
        match stmt {
            AstNode::VarDecl { .. } => Ok(()),
            AstNode::FnDecl { params, .. } => {
                // Validate parameter types
                for (_, ptype) in params {
                    if ptype.is_empty() {
                        return Err("Parameter type cannot be empty".to_string());
                    }
                }
                Ok(())
            },
            AstNode::Block(stmts) => {
                for s in stmts {
                    Self::validate_statement(s)?;
                }
                Ok(())
            },
            AstNode::IfStmt { then_body, else_body, .. } => {
                for s in then_body {
                    Self::validate_statement(s)?;
                }
                if let Some(else_stmts) = else_body {
                    for s in else_stmts {
                        Self::validate_statement(s)?;
                    }
                }
                Ok(())
            },
            AstNode::WhileStmt { body, .. } => {
                for s in body {
                    Self::validate_statement(s)?;
                }
                Ok(())
            },
            AstNode::ForStmt { body, .. } => {
                for s in body {
                    Self::validate_statement(s)?;
                }
                Ok(())
            },
            _ => Ok(()),
        }
    }
}

